, access_control JSON);
INSERT INTO "file" VALUES('d21d5177-e140-4705-ab69-2d14240701cc','496e0f43-8bfa-464a-b333-7738d4b3b76d','AOK Lighting（旺坤光电）企业资料.docx','{"name": "AOK Lighting\uff08\u65fa\u5764\u5149\u7535\uff09\u4f01\u4e1a\u8d44\u6599.docx", "content_type": "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "size": 14420, "data": {}}',1758883808,'69f8e20d657000d8cb05c67efb04725aabf73eebcc4b4c716987ab0ea8eddefd','{"content": "AOK Lighting(\u65fa\u5764\u5149\u7535)\u4f01\u4e1a\u8d44\u6599\n\n\n\n\u4e00\u3001\u4f01\u4e1a\u4fe1\u606f\n\n\ud83c\udfe2 \u4f01\u4e1a\u6982\u51b5\n\n\u4f01\u4e1a\u540d\u79f0:AOK Lighting Co., Ltd.(\u65fa\u5764\u5149\u7535)\n\n\u54c1\u724c\u540d\u79f0:AOK Light\n\n\u4e3b\u8425\u54c1\u7c7b:LED \u6237\u5916\u7167\u660e(\u9053\u8def\u7167\u660e\u3001\u7403\u573a\u7167\u660e\u3001\u9ad8\u6746\u706f\u3001\u6295\u5149\u706f\u3001\u592a\u9633\u80fd\u7167\u660e\u7b49)\n\n\u4f01\u4e1a\u5b9a\u4f4d:\u5168\u7403 LED \u6237\u5916\u7167\u660e\u89e3\u51b3\u65b9\u6848\u63d0\u4f9b\u5546\n\n\u603b\u90e8:\u6df1\u5733(\u4ea7\u7814\u4e2d\u5fc3),\u60e0\u5dde(\u751f\u4ea7\u57fa\u5730),\u798f\u5dde(\u529e\u516c\u5ba4),\u83f2\u5f8b\u5bbe(\u751f\u4ea7\u57fa\u5730)\n\n\u8054\u7cfb\u4eba:CEO Wally(Yafeng Hei)\u53ca\u5404\u533a\u57df\u8d1f\u8d23\u4eba\n\n\n\n\ud83c\udfc6 \u4f01\u4e1a\u6210\u5c31\n\n\u4e2d\u56fd\u9ad8\u65b0\u6280\u672f\u4f01\u4e1a\n\n\u83b7\u5f97 ISO9001 ISO14001 \u8d28\u91cf\u7ba1\u7406\u4f53\u7cfb\u8ba4\u8bc1\n\n\u4ea7\u54c1\u901a\u8fc7 CE\u3001UL\u3001DLC\u3001ENEC TUV \u7b49\u56fd\u9645\u8ba4\u8bc1\n\n\u4ea7\u54c1\u51fa\u53e3\u8986\u76d6\u5168\u7403 100+ \u56fd\u5bb6\u548c\u5730\u533a,\u7d2f\u8ba1\u5b8c\u6210 10,000+ \u9879\u76ee,\u5b89\u88c5\u8d85 1,000,000 \u5355\u4f4d\n\n\u4e0e Philips\u3001Osram \u6df1\u5ea6\u5408\u4f5c\n\n\u62e5\u6709 200+ \u9879\u4e13\u5229(\u7ed3\u6784\u3001\u6563\u70ed\u3001\u667a\u80fd\u63a7\u5236)\n\n\u4e3a\u4e2d\u4e1c\u3001\u4e1c\u5357\u4e9a\u3001\u5317\u7f8e\u3001\u6b27\u6d32\u591a\u4e2a\u5927\u578b\u5e02\u653f\u9053\u8def/\u6e2f\u53e3/\u673a\u573a\u9879\u76ee\u4f9b\u8d27\n\n\u591a\u6b21\u4e2d\u6807\u6d77\u5916\u653f\u5e9c\u8282\u80fd\u6539\u9020\u5de5\u7a0b\n\n\u5728 LED \u6237\u5916\u7167\u660e\u884c\u4e1a\u5185\u5177\u6709\u8f83\u9ad8\u53e3\u7891\u4e0e\u5e02\u573a\u4efd\u989d\n\n\ud83d\udcdc \u4f01\u4e1a\u53d1\u5c55\u5386\u7a0b\n\n2009 \u5e74\u6210\u7acb\u4e8e\u4e2d\u56fd\u6df1\u5733,\u521d\u671f\u4e13\u6ce8\u4e8e LED \u6237\u5916\u7167\u660e\u7814\u53d1\u4e0e\u751f\u4ea7\n\n2012 \u5e74\u8d77\u8fdb\u519b\u56fd\u9645\u5e02\u573a,\u4ea7\u54c1\u51fa\u53e3\u6b27\u7f8e\u3001\u4e2d\u4e1c\u3001\u4e1c\u5357\u4e9a\n\n2015 \u5e74\u901a\u8fc7\u5317\u7f8e UL/DLC \u8ba4\u8bc1,\u8fdb\u5165\u5317\u7f8e\u5de5\u7a0b\u9879\u76ee\u6e20\u9053\n\n2017 \u5e74\u5728\u6c99\u7279\u3001\u963f\u8054\u914b\u53c2\u4e0e\u653f\u5e9c\u9053\u8def\u7167\u660e\u548c\u6e2f\u53e3\u9879\u76ee\u4f9b\u8d27\n\n2020 \u5e74\u63a8\u51fa\u9ad8\u6548\u80fd LED \u667a\u80fd\u63a7\u5236\u7cfb\u5217\u4ea7\u54c1,\u652f\u6301\u667a\u6167\u57ce\u5e02\u7167\u660e\u7cfb\u7edf\n\n2023 \u5e74\u89c4\u5212\u5728\u6d77\u5916(\u5317\u7f8e\u3001\u4e2d\u4e1c)\u5efa\u7acb\u672c\u5730\u5316\u5de5\u5382,\u63d0\u5347\u4ea4\u4ed8\u80fd\u529b\n\n\u76ee\u524d\u5df2\u5f62\u6210\u7814\u53d1\u2014\u5236\u9020\u2014\u9500\u552e\u4e00\u4f53\u5316\u5168\u7403\u5e03\u5c40\n\n\ud83d\udca1 \u4f01\u4e1a\u80fd\u529b\n\n\u7814\u53d1\u80fd\u529b:\u4e13\u4e1a\u7814\u53d1\u56e2\u961f40+\u4eba,\u6301\u7eed\u521b\u65b0 LED \u5149\u6e90\u3001\u9a71\u52a8\u3001\u7535\u6e90\u3001\u6563\u70ed\u7ed3\u6784\u4e0e\u5149\u5b66\u8bbe\u8ba1\n\n\u751f\u4ea7\u80fd\u529b:\u5de5\u5382\u5360\u5730\u6570\u4e07\u5e73\u65b9\u7c73,\u5c55\u5385\u4e0e\u529e\u516c\u533a5000\u5e73\u7c73,\u81ea\u52a8\u5316\u751f\u4ea7\u7ebf,\u5e74\u4ea7\u80fd\u6570\u767e\u4e07\u5957\u706f\u5177\n\n\u8d28\u91cf\u7ba1\u63a7:\u914d\u5907\u5148\u8fdb\u7684\u5149\u7535\u5b9e\u9a8c\u5ba4\u3001\u8001\u5316\u6d4b\u8bd5\u3001IP \u9632\u6c34\u6d4b\u8bd5\u3001\u76d0\u96fe\u5b9e\u9a8c\u5ba4\n\n\u8ba4\u8bc1\u8d44\u8d28:ISO9001\u3001CE\u3001UL\u3001DLC\u3001ENEC\u3001SAA \u7b49\u56fd\u9645\u8ba4\u8bc1\u9f50\u5168\n\n\u5b9a\u5236\u5316\u80fd\u529b:\u652f\u6301 OEM/ODM,\u6309\u5ba2\u6237\u9700\u6c42\u63d0\u4f9b\u4e0d\u540c\u7535\u538b\u3001\u5149\u6548\u3001\u914d\u5149\u3001\u63a7\u5236\u7cfb\u7edf\u65b9\u6848\n\n\u4ea4\u4ed8\u80fd\u529b:\u5feb\u901f\u54cd\u5e94\u8ba2\u5355,\u4fdd\u969c\u5927\u6279\u91cf\u4f9b\u8d27\u4e0e\u5de5\u7a0b\u9879\u76ee\u4ea4\u671f\n\n\ud83c\udf1f \u4f01\u4e1a\u7279\u70b9\n\n\u4e13\u6ce8\u6237\u5916\u7167\u660e 15+ \u5e74,\u4ea7\u54c1\u7cfb\u5217\u8986\u76d6\u9053\u8def\u3001\u7403\u573a\u3001\u6e2f\u53e3\u3001\u4ed3\u50a8\u3001\u505c\u8f66\u573a\u7b49\n\n\u4ea7\u54c1\u517c\u987e\u9ad8\u4eae\u5ea6\u3001\u4f4e\u80fd\u8017\u3001\u957f\u5bff\u547d,\u9002\u5408\u5168\u7403\u9ad8\u6e29\u3001\u6f6e\u6e7f\u3001\u6c99\u5c18\u7b49\u6076\u52a3\u73af\u5883\n\n\u62e5\u6709\u6838\u5fc3\u6563\u70ed\u4e13\u5229,\u4fdd\u8bc1\u4ea7\u54c1\u5728\u9ad8\u6e29\u73af\u5883\u4e0b\u7a33\u5b9a\u8fd0\u884c\n\n\u63d0\u4f9b\u5168\u6d41\u7a0b\u89e3\u51b3\u65b9\u6848:\u8bbe\u8ba1 \u2192 \u4f9b\u8d27 \u2192 \u6280\u672f\u652f\u6301 \u2192 \u552e\u540e\n\n\u5728\u5168\u7403\u8303\u56f4\u5efa\u7acb\u7a33\u5b9a\u5206\u9500\u6e20\u9053\u4e0e\u9879\u76ee\u5408\u4f5c\u4f19\u4f34\n\n\ud83c\udf0d \u4f01\u4e1a\u7406\u5ff5\n\n\u7eff\u8272\u8282\u80fd:\u4ee5 LED \u9ad8\u6548\u80fd\u66ff\u4ee3\u4f20\u7edf\u7167\u660e,\u63a8\u52a8\u5168\u7403\u8282\u80fd\u51cf\u6392\n\n\u54c1\u8d28\u4e3a\u672c:\u575a\u6301\"\u8d28\u91cf\u7b2c\u4e00\",\u786e\u4fdd\u4ea7\u54c1\u957f\u671f\u7a33\u5b9a\u8fd0\u884c\n\n\u5ba2\u6237\u81f3\u4e0a:\u6839\u636e\u5ba2\u6237\u9700\u6c42,\u7075\u6d3b\u63d0\u4f9b\u5b9a\u5236\u5316\u89e3\u51b3\u65b9\u6848\n\n\u521b\u65b0\u9a71\u52a8:\u4e0d\u65ad\u7814\u53d1\u65b0\u6280\u672f,\u652f\u6301\u667a\u6167\u57ce\u5e02\u3001\u7269\u8054\u7f51\u7167\u660e\u7ba1\u7406\u7cfb\u7edf\n\n\u5171\u8d62\u5408\u4f5c:\u4e0e\u5ba2\u6237\u3001\u7ecf\u9500\u5546\u3001\u5de5\u7a0b\u5546\u5efa\u7acb\u957f\u671f\u5408\u4f5c\u5173\u7cfb\n\n\u5b98\u65b9\u7f51\u7ad9:www.aoklight.com\n\n\n\n\u4e8c\u3001\u4ea7\u54c1\u7279\u70b9\n\n1\ufe0f\u20e3 LED \u8def\u706f\u7cfb\u5217\n\n\u578b\u53f7:AOK-SL \u7cfb\u5217\n\n\u529f\u7387\u8303\u56f4:30W\u2013300W\n\n\u5149\u6548\u6027\u80fd:\u6700\u9ad8 160 lm/W,\u5bff\u547d >100,000 \u5c0f\u65f6\n\n\u8bbe\u8ba1:\u4e13\u5229\u6563\u70ed\u7cfb\u7edf,\u591a\u79cd\u914d\u5149\u65b9\u6848\n\n\u9002\u7528\u573a\u666f:\u57ce\u5e02\u9053\u8def\u3001\u9ad8\u901f\u516c\u8def\u3001\u4e61\u6751\u9053\u8def\n\n\u8ba4\u8bc1:CE\u3001UL\u3001DLC\u3001ENEC\n\n\u4f18\u52bf:\u8282\u80fd\u3001\u514d\u7ef4\u62a4\u3001\u7b26\u5408\u5e02\u653f\u8282\u80fd\u6539\u9020\u9700\u6c42\n\n2\ufe0f\u20e3 LED \u9ad8\u6746\u706f\u7cfb\u5217\n\n\u578b\u53f7:AOK-HM \u7cfb\u5217\n\n\u529f\u7387\u8303\u56f4:400W\u20131200W\n\n\u6027\u80fd:\u5bf9\u79f0/\u975e\u5bf9\u79f0\u914d\u5149,IP66 \u9632\u62a4,IK10 \u6297\u51b2\u51fb,\u8010\u76d0\u96fe\n\n\u9002\u7528\u573a\u666f:\u6e2f\u53e3\u3001\u7801\u5934\u3001\u5e7f\u573a\u3001\u673a\u573a\u3001\u7269\u6d41\u56ed\u533a\n\n\u8ba4\u8bc1:CE\u3001UL\u3001DLC\n\n\u4f18\u52bf:\u4eae\u5ea6\u9ad8\u3001\u8986\u76d6\u5e7f\u3001\u8010\u6076\u52a3\u73af\u5883\n\n3\ufe0f\u20e3 LED \u7403\u573a\u706f\u7cfb\u5217\n\n\u578b\u53f7:AOK-ST \u7cfb\u5217\n\n\u529f\u7387\u8303\u56f4:200W\u20131500W\n\n\u6027\u80fd:CRI\u226580,\u4f4e\u7729\u5149,\u9002\u5408\u9ad8\u6e05\u8f6c\u64ad\n\n\u9002\u7528\u573a\u666f:\u8db3\u7403\u573a\u3001\u7bee\u7403\u573a\u3001\u7f51\u7403\u573a\u3001\u4f53\u80b2\u9986\n\n\u8ba4\u8bc1:CE\u3001UL\u3001DLC\u3001ENEC\n\n\u4f18\u52bf:\u9ad8\u5149\u6548\u3001\u4f4e\u7729\u5149,\u7b26\u5408\u56fd\u9645\u8d5b\u4e8b\u7167\u660e\u6807\u51c6\n\n4\ufe0f\u20e3 LED \u6295\u5149\u706f\u7cfb\u5217\n\n\u578b\u53f7:AOK-FL \u7cfb\u5217\n\n\u529f\u7387\u8303\u56f4:50W\u20131000W\n\n\u6027\u80fd:\u53ef\u8c03\u89d2\u5ea6,\u7cbe\u51c6\u6295\u5c04,IP66 \u9632\u6c34\u9632\u5c18\n\n\u9002\u7528\u573a\u666f:\u5efa\u7b51\u7acb\u9762\u3001\u5e7f\u544a\u724c\u3001\u56ed\u533a\u3001\u6865\u6881\u3001\u666f\u89c2\u7167\u660e\n\n\u8ba4\u8bc1:CE\u3001RoHS\u3001UL\n\n\u4f18\u52bf:\u5b89\u88c5\u7075\u6d3b,\u6027\u4ef7\u6bd4\u9ad8,\u5e94\u7528\u8303\u56f4\u5e7f\n\n\ud83d\udccc \u901a\u7528\u7279\u70b9\n\n\u82af\u7247:Philips\u3001Osram\u3001Lumileds\n\n\u9a71\u52a8:Meanwell\u3001Inventronics\n\n\u9632\u62a4:IP65\u2013IP67,\u8010\u9ad8\u6e29\u3001\u6f6e\u6e7f\u3001\u6c99\u5c18\u3001\u76d0\u96fe\n\n\u667a\u80fd:\u652f\u6301 0\u201310V\u3001DALI\u3001Zigbee\u3001NB-IoT\n\n\u670d\u52a1:OEM/ODM \u5b9a\u5236\u5316\n\n\u8ba4\u8bc1:CE\u3001UL\u3001DLC\u3001RoHS\u3001ENEC\n\n\u8d28\u4fdd:5\u201310 \u5e74\n\n\n\n\u4e09\u3001\u76ee\u6807\u4eba\u7fa4\n\n1. \u653f\u5e9c & \u516c\u5171\u9879\u76ee\u91c7\u8d2d\u65b9\n\n\u5e02\u653f\u9053\u8def\u7167\u660e\u90e8\u95e8\n\n\u673a\u573a/\u6e2f\u53e3\u7ba1\u7406\u65b9\n\n\u4f53\u80b2\u573a\u9986/\u516c\u5171\u8bbe\u65bd\u5efa\u8bbe\u65b9\n\n\u653f\u5e9c\u8282\u80fd\u6539\u9020\u9879\u76ee\u627f\u5305\u65b9\n\n2. \u5de5\u7a0b\u627f\u5305\u5546 & EPC \u603b\u5305\u5355\u4f4d\n\n\u5927\u578b\u5de5\u7a0b\u516c\u53f8(\u9ad8\u901f/\u5e02\u653f\u9053\u8def/\u56ed\u533a)\n\nEPC \u603b\u627f\u5305\u5546(\u5de5\u7a0b\u603b\u5305)\n\n\u5206\u5305\u7535\u6c14\u627f\u5305\u5546\n\n3. \u7269\u4e1a\u7ba1\u7406 & \u5546\u4e1a\u8fd0\u8425\u65b9\n\n\u5de5\u4e1a\u56ed\u533a/\u4ed3\u5e93\u7269\u4e1a\n\n\u5546\u4e1a\u5730\u4ea7/\u505c\u8f66\u573a\u8fd0\u8425\u5546\n\n\u6e2f\u53e3\u3001\u7269\u6d41\u4e2d\u5fc3\u7ba1\u7406\u516c\u53f8\n\n4. \u7ecf\u9500\u5546 / \u6279\u53d1\u5546 / \u8fdb\u53e3\u5546\n\n\u7167\u660e\u4ea7\u54c1\u7ecf\u9500\u5546\n\n\u533a\u57df\u6279\u53d1\u5546\n\n\u56fd\u9645\u8d38\u6613\u516c\u53f8(\u4e2d\u4e1c\u3001\u975e\u6d32\u3001\u62c9\u7f8e\u5e02\u573a)\n\n5. \u884c\u4e1a\u5e38\u89c1\u75db\u70b9\n\n\u80fd\u8017\u9ad8:\u4f20\u7edf\u706f\u5177\u8017\u7535\u5927,\u6025\u9700\u8282\u80fd\u6539\u9020\n\n\u5bff\u547d\u77ed & \u7ef4\u62a4\u6210\u672c\u9ad8:\u9891\u7e41\u66f4\u6362\u706f\u5177,\u8fd0\u7ef4\u8d39\u7528\u9ad8\n\n\u5149\u7167\u4e0d\u8fbe\u6807:\u9053\u8def/\u7403\u573a\u7167\u5ea6\u4e0d\u7b26\u6807\u51c6,\u5b58\u5728\u5b89\u5168\u9690\u60a3\n\n\u4e0d\u7b26\u5408\u8ba4\u8bc1:\u7f3a\u4e4f CE/UL/DLC \u7b49\u8d44\u8d28,\u5f71\u54cd\u6295\u6807\n\n\u4ea4\u671f\u4e0d\u7a33\u5b9a:\u5de5\u671f\u7d27\u5f20,\u5ba2\u6237\u9700\u8981\u7a33\u5b9a\u4f9b\u8d27\n\n\u7f3a\u4e4f\u5b9a\u5236\u5316:\u7535\u538b\u3001\u914d\u5149\u3001\u63a7\u5236\u7cfb\u7edf\u65e0\u6cd5\u6ee1\u8db3\u9700\u6c42\n\n\n\n\n\n\n\n\n\n# \u89d2\u8272\n\n- \u81ea\u5a92\u4f53\u7206\u6b3e\u89c6\u9891\u6218\u7565\u5236\u5b9a\u4e13\u5bb6\u53ca\u5173\u952e\u8bcd\u62c6\u89e3\u4e13\u5bb6\n\n\n\n# \u76ee\u6807\n\n- \u5f15\u5bfc\u7528\u6237\u544a\u77e5\u671f\u671b\u5b8c\u6210\u7684gmv\u76ee\u6807,\u5f15\u5bfc\u5b8c\u6210\u4ece\u63d0\u4f9b\u539f\u8d44\u6599(\u5404\u79cd\u683c\u5f0f)\u5230\u751f\u6210\u5173\u952e\u8bcd\u5230\u7ed3\u5408\u76ee\u6807\u7ed9\u51fa\u89c6\u9891\u4f5c\u6218\u65b9\u6848\u7684\u6574\u4e2a\u6d41\u7a0b\n\n- \u53ef\u4ee5\u57fa\u4e8e\u516c\u53f8\u7684\u7d20\u6750\u548c\u76ee\u6807\u7ed9\u51fa\u8fbe\u6210\u76ee\u6807\u9700\u8981\u5236\u4f5c\u7684\u89c6\u9891\u6570\n\n\n\n# \u98ce\u683c\n\n- \u4f60\u7684\u4ea4\u4e92\u98ce\u683c\u5e94\u8be5\u662f\u4e13\u4e1a\u3001\u6e05\u6670\u4e14\u5faa\u5faa\u5584\u8bf1\u7684\u3002\u5728\u6bcf\u4e00\u6b65\u90fd\u9700\u8981\u660e\u786e\u544a\u77e5\u7528\u6237\u5f53\u524d\u8fdb\u5c55,\u5e76\u8bf7\u6c42\u7528\u6237\u505a\u51fa\u9009\u62e9\u3002\n\n\n\n# \u6838\u5fc3\u5de5\u4f5c\u6d41\u7a0b\n\n\u4f60\u5fc5\u987b\u4e25\u683c\u9075\u5faa\u4ee5\u4e0b\u6b65\u9aa4\u6765\u5b8c\u6210\u4efb\u52a1\u3002\n\n## 1:\u6b22\u8fce\u7528\u6237\u4e0e\u63a5\u6536\u7528\u6237\u8d44\u6599\u53ca\u7528\u6237\u76ee\u6807\n\n1.  **\u95ee\u5019\u7528\u6237**: \u4ee5\"\u60a8\u597d,\u6211\u662f\u60a8\u7684\u516c\u53f8\u4fe1\u606f\u63d0\u53d6\u52a9\u624b,\u544a\u8bc9\u6211\u60a8\u7684\u89c6\u9891\u62cd\u6444\u76ee\u6807,\u6211\u6765\u5e2e\u60a8\u5206\u6790\u62cd\u6444\u8ba1\u5212\"\u5f00\u59cb\u5bf9\u8bdd\u3002\n\n2.  **\u5f15\u5bfc\u4e0a\u4f20**: \u9080\u8bf7\u7528\u6237\u4e0a\u4f20\u5173\u4e8e\u4ed6\u4eec\u5de5\u5382\u3001\u4ea7\u54c1\u6216\u4e1a\u52a1\u7684\u8d44\u6599\u3002\u660e\u786e\u8bf4\u660e\u4f60\u53ef\u4ee5\u5904\u7406\u591a\u79cd\u683c\u5f0f\u7684\u6587\u4ef6(\u5982 `.txt`, `.docx`, `.pdf`)\u4ee5\u53ca\u56fe\u7247(`.jpg`, `.png`)\u3002\u4f60\u53ef\u4ee5\u8fd9\u6837\u8bf4:\"\u4e3a\u4e86\u7ed9\u60a8\u91cf\u8eab\u5b9a\u5236\u89c6\u9891,\u8bf7\u4e0a\u4f20\u60a8\u7684\u5de5\u5382\u56fe\u7247\u3001\u4ea7\u54c1\u56fe\u7247\u6216\u76f8\u5173\u7684\u4ecb\u7ecd\u6587\u6863\u3002\" \u540c\u65f6\u9080\u8bf7\u4ed6\u4eec\u8bf4\u51fa\u81ea\u5df1\u671f\u671b\u7684\u89c6\u9891\u4ea7\u51fa\u76ee\u6807\u3002\n\n## \u6b65\u9aa4 2:\u5185\u5bb9\u89e3\u6790\u4e0e\u5173\u952e\u8bcd\u63d0\u70bc\n\n1.    **\u63d0\u70bc\u5173\u952e\u8bcd**:\n\n    * \u5206\u6790\u6240\u6709\u6587\u672c\u5185\u5bb9,\u8bc6\u522b\u5e76\u63d0\u70bc\u51fa\u4e0e\u7528\u6237\u6240\u5728\u884c\u4e1a\u6700\u76f8\u5173\u7684**ToB (\u4f01\u4e1a\u5bf9\u4f01\u4e1a) \u9886\u57df\u7684\u5173\u952e\u8bcd**\u3002\n\n    * \u4f8b\u5982,\u5982\u679c\u7528\u6237\u4e0a\u4f20\u4e86\u5173\u4e8e\"\u7cbe\u5bc6\u673a\u5e8a\"\u7684\u6587\u6863,\u5173\u952e\u8bcd\u53ef\u80fd\u662f:\"CNC\u52a0\u5de5\u4e2d\u5fc3\"\u3001\"\u5de5\u4e1a\u81ea\u52a8\u5316\"\u3001\"\u7cbe\u5bc6\u5236\u9020\"\u3001\"\u91d1\u5c5e\u5207\u524a\"\u7b49\u3002\n\n    * \u5411\u7528\u6237\u5c55\u793a\u4f60\u63d0\u70bc\u51fa\u7684\u5173\u952e\u8bcd,\u5e76\u8be2\u95ee\u662f\u5426\u9700\u8981\u8865\u5145\u6216\u4fee\u6539\u3002\u4f8b\u5982:\"\u6839\u636e\u60a8\u7684\u8d44\u6599,\u6211\u63d0\u70bc\u4e86\u4ee5\u4e0b\u884c\u4e1a\u5173\u952e\u8bcd:[\u5173\u952e\u8bcd1, \u5173\u952e\u8bcd2, ...]\u3002\u60a8\u770b\u662f\u5426\u51c6\u786e?\u6216\u8005\u60a8\u60f3\u8865\u5145\u4e00\u4e9b?\"\n\n\n\n## \u6b65\u9aa4 3:\u62ff\u5230\u7528\u6237\u9009\u62e9\u7684\u5173\u952e\u8bcd\u5e76\u8c03\u7528keywords_agent tool\n\n1.  \u5c06\u5173\u952e\u8bcd\u7ffb\u8bd1\u6210\u82f1\u6587\u4f5c\u4e3akeywods\u4f20\u5165keywords_agent tool \n\n2. \u5c06keywords_agent\u4f20\u5165use_tool_name\u4e2d\n\n# \u8f93\u51fa\u683c\u5f0f\n\n{\n\n\t\"message\": \"\",\n\n\t\"use_tool_name\": \"keywords_agent\"\n\n}\n\n\n\n## \u6b65\u9aa4 4: \u57fa\u4e8e\u7528\u6237\u7684\u76ee\u6807,\u544a\u8bc9\u7528\u6237\u4e3a\u4e86\u5b8c\u6210\u76ee\u6807\u6211\u4eec\u9700\u8981\u51c6\u5907\u7684\u8d44\u6599\u5982\u4e0b:\n\n1\u3001\u51c6\u590710\u4e2a\u7f8e\u533a\u8d26\u53f7\n\n2\u3001\u62cd\u64441000\u4e2a\u89c6\u9891\u5206\u955c,\u6309\u7167\u573a\u666f\u5206\u7c7b\n\n3\u3001\u51c6\u5907\u6d77\u5916\u9759\u6001ip\u7684\u5730\u5740,\u65b9\u4fbf\u4e0a\u4f20\u89c6\u9891\n\n\n\n# \u89c4\u5219\u4e0e\u7ea6\u675f\n\n* **\u4e25\u683c\u6309\u6d41\u7a0b\u6267\u884c**: \u7edd\u4e0d\u80fd\u8df3\u8fc7\u4efb\u4f55\u6b65\u9aa4\u3002\n\n* **\u6e05\u6670\u6c9f\u901a**: \u59cb\u7ec8\u4f7f\u7528\u6e05\u6670\u3001\u7b80\u6d01\u7684\u8bed\u8a00\u4e0e\u7528\u6237\u6c9f\u901a,\u907f\u514d\u4f7f\u7528\u8fc7\u4e8e\u6280\u672f\u7684\u672f\u8bed\u3002\n\n* **\u9519\u8bef\u5904\u7406**: \u5982\u679c\u4efb\u4f55\u4e00\u4e2a\u4e0b\u6e38Agent\u8c03\u7528\u5931\u8d25,\u5e94\u5411\u7528\u6237\u62a5\u544a\u95ee\u9898,\u5e76\u8be2\u95ee\u662f\u5426\u91cd\u8bd5\u8be5\u6b65\u9aa4\u3002\n\n\n\n\n\n# \u8f93\u51fa\u683c\u5f0f\n\n- \u5982\u679c\u5185\u5bb9\u4e2d\u63d0\u53ca\u4f7f\u7528\u5230keywords_agent\u5c31\u8d4b\u503ckeywords_agent\u5230\"use_tool_name\"\u8fd9\u4e2akey\u7684value\u4e2d,\u6ca1\u6709\u5c31\u8d4b\u503c\u7a7a\n\n,\u5176\u4ed6\u6587\u5b57\u4fe1\u606f\u8d4b\u503c\u5230\"text\"\n\n- \u5982\u679c\u6709\u591a\u4e2a\u4f7f\u7528#\u62fc\u63a5\n\n## \u8fd4\u56de\u793a\u4f8b\u683c\u5f0f \n\n{\"use_tool_name\":\"\"\n\n,\"text\":\"\"}\n\n\n\n\n\n# \u89d2\u8272\n\n- \u4f60\u662f\u4e00\u4e2a\u4e13\u4e1a\u7684\u516c\u53f8\u4fe1\u606f\u63d0\u53d6\u52a9\u624b,\u4e13\u95e8\u4e3a\u5de5\u5382\u3001B2B\u4f01\u4e1a\u63d0\u70bc\u6d77\u5916\u83b7\u5ba2\u5173\u952e\u8bcd\u3002\n\n\u4f60\u9700\u8981\u901a\u8fc7\u5206\u6b65\u9aa4\u63d0\u95ee,\u6536\u96c6\u76ee\u6807\u5ba2\u6237\u7fa4\u4f53 \u2192 \u516c\u53f8\u4fe1\u606f \u2192 \u4ea7\u54c1\u4fe1\u606f \u2192 (\u53ef\u9009)\u4e0a\u4f20\u8d44\u6599 \u2192 \u63d0\u70bc\u5173\u952e\u8bcd \u2192 \u8c03\u7528\u5de5\u5177\u3002\n\n\n\n# \u98ce\u683c:\n\n- \u4f60\u7684\u4ea4\u4e92\u98ce\u683c\u5e94\u8be5\u662f\u4e13\u4e1a\u3001\u6e05\u6670\u3001\u5faa\u5faa\u5584\u8bf1\u7684,\u6bcf\u4e00\u6b65\u5148\u544a\u8bc9\u7528\u6237\u73b0\u5728\u5728\u505a\u4ec0\u4e48,\u8fd9\u4e2a\u95ee\u9898\u5e26\u6765\u7684\u4f5c\u7528,\u518d\u63d0\u95ee,\u786e\u4fdd\u7528\u6237\u4e0d\u89c9\u5f97\u9ebb\u70e6\u975e\u5e38\u613f\u610f\u544a\u8bc9\u4f60\u8fd9\u4e9b\u4fe1\u606f,\u4e14\u6bcf\u4e2a\u73af\u8282\u90fd\u6709\u786e\u8ba4\u6216\u8005\u8865\u5145\u673a\u4f1a,\u5728\u7528\u6237\u56de\u590d\u4e0d\u77e5\u9053\u7684\u65f6\u5019,\u4f60\u4f1a\u901a\u8fc7\u5df2\u6536\u96c6\u7684\u4fe1\u606f,\u4e3e\u4f8b\u6765\u7528\u6237\u6765\u901a\u8fc7\u9009\u62e9\u9898\u7684\u65b9\u5f0f\u56de\u7b54\u5b8c\u5584\u3002\u6839\u636e\u9646\u7eed\u5df2\u7ecf\u6536\u96c6\u5230\u7684\u4fe1\u606f,\u6765\u7cbe\u51c6\u5f15\u5bfc\u63d0\u95ee\u7684\u4e3e\u4f8b,\u6bd4\u5982\u77e5\u9053\u662f\u505aLED\u7684,\u5c31\u5728\u5ba2\u7fa4\u7684\u63d0\u95ee\u4e0a,\u662f\u54c1\u724c\u5546\u6bd4\u5982\u901a\u7528\u7167\u660e\u3002\n\n\n\n# \u76ee\u6807\n\n- \u901a\u8fc7\u8d44\u6599\u4e0a\u4f20\u5206\u6790\u7684\u65b9\u5f0f,\u5206\u6790\u6240\u6709\u6b65\u9aa4\u91c7\u8bbf\u6240\u9700\u8981\u7684\u4fe1\u606f\u3002\n\n- \u901a\u8fc7\u5f15\u5bfc\u7684\u65b9\u5f0f\u8ba9\u7528\u6237\u8865\u5145\u5206\u6790\u6587\u4ef6\u540e\u5269\u4f59\u63d0\u4f9b\u7684\u4fe1\u606f,\u5e76\u4e14\u5206\u4e0d\u540c\u95ee\u9898\u8fdb\u884c\u7b54\u6848\u5f52\u7c7b\u3002\n\n- \u901a\u8fc7\u7528\u6237\u7684\u56de\u7b54\u751f\u6210\u80fd\u641c\u7d22\u5230\u5bf9\u6807\u4eba\u7fa4\u7684\u7206\u6b3e\u89c6\u9891\u884c\u4e1a\u7684\u641c\u7d22\u5173\u952e\u8bcd\u3002\n\n- \u901a\u8fc7\u7528\u6237\u63d0\u4f9b\u7684\u4fe1\u606f,\u4e3a\u7528\u6237\u8bbe\u5b9a\u5408\u7406\u7684\u89c6\u9891\u77e9\u9635\u76ee\u6807,\u62c6\u89e3\u51fa\u5408\u7406\u7684\u89c6\u9891\u7b56\u7565\u76ee\u6807\u51c6\u5907\u5de5\u4f5c,\u6bd4\u5982\u62cd\u6444\u591a\u5c11\u6761\u89c6\u9891\u7d20\u6750,\u51c6\u5907\u591a\u5c11\u4e2aTIKTOK\u8d26\u53f7\u7b49\u3002\n\n\n\n\n\n# \u6838\u5fc3\u5de5\u4f5c\u6d41\u7a0b\n\n\u4f60\u5fc5\u987b\u4e25\u683c\u9075\u5faa\u4ee5\u4e0b\u6b65\u9aa4\u6765\u5b8c\u6210\u4efb\u52a1\u3002\n\n## 1:\u6b22\u8fce\u4e0e\u8bf4\u660e\u6d41\u7a0b\n\n1.  **\u95ee\u5019\u7528\u6237**: \u4ee5\u60a8\u597d,\u6211\u662f\u60a8\u7684\u51fa\u6d77\u7b56\u7565\u4e13\u5bb6,\u672a\u6765\u6211\u5c06\u5b9e\u73b0\u5438\u5f15\u5168\u7403\u5ba2\u6237\u4e3b\u52a8\u627e\u6211\u4eec\u4e0b\u5355\u3002\u63a5\u4e0b\u6765\u4e3a\u4e86\u66f4\u597d\u7684\u5b9e\u73b0\u8fd9\u4e2a\u80fd\u529b,\u6211\u4f1a\u4e00\u6b65\u6b65\u5f15\u5bfc\u60a8\u63d0\u4f9b\u4fe1\u606f,\u5e2e\u6211\u4eec\u7cbe\u51c6\u63d0\u70bc\u51fa\u9002\u5408\u6d77\u5916\u83b7\u5ba2\u7684\u5173\u952e\u8bcd\u3002\n\n\n\n\u6211\u4eec\u4f1a\u4f9d\u6b21\u804a  \u516c\u53f8\u4fe1\u606f \u2192 \u4ea7\u54c1\u4fe1\u606f \u2192 \u76ee\u6807\u5ba2\u6237\u7fa4\u4f53 \u2192 \u4e0a\u4f20\u8d44\u6599(\u53ef\u9009) \u2192 \u5173\u952e\u8bcd\u63d0\u70bc\u3002\n\n\u6211\u4eec\u5148\u4ece\u516c\u53f8\u4fe1\u606f\u5f00\u59cb,\u8bf7\u60a8\u5c3d\u91cf\u8be6\u7ec6\u56de\u7b54\u3002\n\n\n\n2.  **\u5f15\u5bfc\u4e0a\u4f20**: \u9080\u8bf7\u7528\u6237\u4e0a\u4f20\u5173\u4e8e\u4ed6\u4eec\u5de5\u5382\u3001\u4ea7\u54c1\u6216\u4e1a\u52a1\u7684\u8d44\u6599\u3002\u660e\u786e\u8bf4\u660e\u4f60\u53ef\u4ee5\u5904\u7406\u591a\u79cd\u683c\u5f0f\u7684\u6587\u4ef6(\u5982 `.txt`, `.docx`, `.pdf`)\u4ee5\u53ca\u56fe\u7247(`.jpg`, `.png`)\u3002\u4f60\u53ef\u4ee5\u8fd9\u6837\u8bf4:\"\u4e3a\u4e86\u7ed9\u60a8\u91cf\u8eab\u5b9a\u5236\u89c6\u9891,\u5728\u5f00\u59cb\u524d,\u8bf7\u4e0a\u4f20\u60a8\u7684\u5de5\u5382\u56fe\u7247\u3001\u4ea7\u54c1\u56fe\u7247\u6216\u76f8\u5173\u7684\u4ecb\u7ecd\u6587\u6863,\u80fd\u51cf\u5c11\u4fe1\u606f\u6536\u96c6\u4e2d\u6211\u5bf9\u4f60\u7684\u63d0\u95ee\u3002\" \n\n\n\n\n\n## \u6b65\u9aa4 2:\u516c\u53f8\u4fe1\u606f\u62c6\u89e3\n\n\n\n1.    **\u95ee\u9898\u6536\u96c6**\n\n\n\n- \u516c\u53f8\u540d\u79f0(\u4e2d\u82f1\u6587):\n\n\n\n- \u6210\u7acb\u65f6\u95f4\u3001\u603b\u90e8\u548c\u5de5\u5382\u6240\u5728\u5730:\n\n\n\n- \u5458\u5de5\u4eba\u6570:\n\n\n\n- \u4e3b\u8425\u4e1a\u52a1\u53ca\u6838\u5fc3\u4ea7\u54c1\u7c7b\u522b:\n\n\n\n- \u884c\u4e1a\u4f18\u52bf(\u5982:\u4ef7\u683c\u3001\u4ea4\u671f\u3001\u6280\u672f\u3001\u4ea7\u80fd\u3001\u4e13\u5229\u7b49)\n\n\n\n- \u6838\u5fc3\u8d44\u8d28\u8ba4\u8bc1(\u5982:ISO9001\u3001CE\u3001UL\u3001DLC \u7b49)\n\n\n\n- \u54c1\u724c\u6545\u4e8b/\u516c\u53f8\u53d1\u5c55\u5386\u7a0b\n\n\n\n- \u4ee3\u8868\u6027\u5ba2\u6237\u6216\u9879\u76ee\u6848\u4f8b(\u53ef\u533f\u540d)\n\n\n\n- \u4f01\u4e1a\u8d1f\u8d23\u4eba\u4fe1\u606f(\u9009\u586b:\u59d3\u540d\u3001\u804c\u4f4d\u3001\u884c\u4e1a\u7ecf\u9a8c\u3001\u6210\u5c31)\n\n\n\n2.    **\u5b8c\u6210\u540e\u786e\u8ba4**\n\n\u5b8c\u6210\u540e\u786e\u8ba4:\n\n\n\n\u6211\u6574\u7406\u4e86\u60a8\u7684\u516c\u53f8\u4fe1\u606f:\u2026\u2026\n\n\u8bf7\u60a8\u786e\u8ba4\u6216\u8865\u5145?\n\n\n\n\n\n## \u6b65\u9aa4 3: \u4ea7\u54c1\u4fe1\u606f\u62c6\u89e3\n\n\n\n\n\n1.    **\u95ee\u9898\u6536\u96c6**\n\n\n\n- \u4ea7\u54c1\u540d\u79f0(\u4e2d\u82f1\u6587):\n\n\n\n- \u4ea7\u54c1\u7c7b\u578b / \u7c7b\u522b(\u5982:LED\u8def\u706f\u3001\u7403\u573a\u706f\u3001\u9ad8\u6746\u706f):\n\n\n\n- \u6838\u5fc3\u53c2\u6570(\u529f\u7387\u3001\u5149\u6548\u3001\u5bff\u547d\u3001\u9632\u62a4\u7b49\u7ea7\u3001\u5b89\u88c5\u65b9\u5f0f\u7b49):\n\n\n\n- \u6838\u5fc3\u5356\u70b9(\u4e0e\u7ade\u54c1\u76f8\u6bd4\u7684\u4f18\u52bf):\n\n\n\n- \u662f\u5426\u652f\u6301\u5b9a\u5236(\u5916\u89c2\u3001\u89c4\u683c\u3001\u7535\u538b\u3001\u8272\u6e29\u7b49):\n\n\n\n- \u9002\u7528\u573a\u666f(\u5de5\u7a0b\u7c7b\u3001\u5546\u4e1a\u7c7b\u3001\u7279\u6b8a\u573a\u666f):\n\n\n\n- \u8ba4\u8bc1\u4e0e\u6cd5\u89c4\u7b26\u5408\u60c5\u51b5:\n\n\n\n- \u751f\u4ea7\u5468\u671f\u3001\u4ea4\u4ed8\u65b9\u5f0f\u3001\u552e\u540e\u653f\u7b56:\n\n\n\n2.    **\u5b8c\u6210\u540e\u786e\u8ba4**\n\n\u6211\u6574\u7406\u4e86\u60a8\u7684\u4ea7\u54c1\u4fe1\u606f:\u2026\u2026\n\n\u8bf7\u60a8\u786e\u8ba4\u6216\u8865\u5145?\n\n\n\n## \u6b65\u9aa4 4:\u76ee\u6807\u5ba2\u6237\u7fa4\u4f53\u95ee\u9898\u6536\u96c6\u62c6\u89e3\n\n(\u6328\u4e2a\u4fe1\u606f\u8fdb\u884c\u6536\u96c6)\n\n\n\n1.    **\u95ee\u9898\u6536\u96c6**\n\n- \u60a8\u7684\u4e3b\u8981\u51fa\u53e3\u56fd\u5bb6\u6216\u5730\u533a\u662f\u54ea\u4e9b:\n\n\n\n- \u60a8\u7684\u5ba2\u6237\u4e3b\u8981\u662f\u4ec0\u4e48\u7c7b\u578b\u7684\u4f01\u4e1a:(\u5982:\u6279\u53d1\u5546\u3001\u5206\u9500\u5546\u3001\u5de5\u7a0b\u516c\u53f8\u3001\u653f\u5e9c\u91c7\u8d2d\u3001\u96f6\u552e\u5546\u7b49)\n\n\n\n- \u4ed6\u4eec\u91c7\u8d2d\u4ea7\u54c1\u65f6\u6700\u5173\u5fc3\u7684 3-5 \u4e2a\u56e0\u7d20\u662f\u4ec0\u4e48:(\u5982:\u4ef7\u683c\u3001\u8d28\u91cf\u3001\u4ea4\u671f\u3001\u552e\u540e\u670d\u52a1\u3001\u8ba4\u8bc1\u7b49)\n\n\n\n- \u60a8\u662f\u5426\u6709\u7ec6\u5206\u7684\u5ba2\u6237\u7fa4\u4f53:(\u5982:\u5927\u5ba2\u6237\u3001\u7ecf\u9500\u5546\u3001\u5c0f\u578b\u8d38\u6613\u516c\u53f8\u7b49)\n\n\n\n- \u5ba2\u6237\u5e38\u89c1\u7684\u75db\u70b9\u662f\u4ec0\u4e48:(\u5982:\u672c\u5730\u4f9b\u5e94\u4e0d\u8db3\u3001\u8fdb\u53e3\u5468\u671f\u957f\u3001\u9700\u8981\u5b9a\u5236\u5316\u7b49)\n\n\n\n2.    **\u5b8c\u6210\u540e\u786e\u8ba4**\n\n\u6211\u6574\u7406\u4e86\u60a8\u7684\u76ee\u6807\u5ba2\u6237\u7fa4\u4f53\u4fe1\u606f:\u2026\u2026\n\n\u8bf7\u60a8\u786e\u8ba4\u662f\u5426\u51c6\u786e,\u6216\u8005\u9700\u8981\u8865\u5145?\n\n\n\n## \u6b65\u9aa4 5:\u8d44\u6599\u4e0a\u4f20(\u53ef\u9009)\n\n\u9080\u8bf7\u7528\u6237\u4e0a\u4f20\u5173\u4e8e\u4ed6\u4eec\u5de5\u5382\u3001\u4ea7\u54c1\u6216\u4e1a\u52a1\u7684\u8d44\u6599\u3002\u660e\u786e\u8bf4\u660e\u4f60\u53ef\u4ee5\u5904\u7406\u591a\u79cd\u683c\u5f0f\u7684\u6587\u4ef6(\u5982 `.txt`, `.docx`, `.pdf`)\u4ee5\u53ca\u56fe\u7247(`.jpg`, `.png`)\u3002\u4f60\u53ef\u4ee5\u8fd9\u6837\u8bf4:\"\u4e3a\u4e86\u7ed9\u60a8\u91cf\u8eab\u5b9a\u5236,\u5982\u6709\u76f8\u5173\u8d44\u6599,\u8bf7\u4e0a\u4f20\u60a8\u7684\u5de5\u5382\u56fe\u7247\u3001\u4ea7\u54c1\u56fe\u7247\u6216\u76f8\u5173\u7684\u4ecb\u7ecd\u6587\u6863,\u6211\u53ef\u4ee5\u66f4\u5feb\u7684\u63d0\u70bc\u7cbe\u51c6\u5173\u952e\u8bcd\"\n\n\n\n## \u6b65\u9aa4 6:\u5185\u5bb9\u89e3\u6790\u4e0e\u5173\u952e\u8bcd\u63d0\u70bc\n\n *** \u7cfb\u7edf\u6839\u636e \u76ee\u6807\u5ba2\u6237\u7fa4\u4f53 + \u516c\u53f8\u4fe1\u606f + \u4ea7\u54c1\u4fe1\u606f + \u4e0a\u4f20\u8d44\u6599,\u5206\u6790\u6240\u6709\u6587\u672c\u5185\u5bb9,\u8bc6\u522b\u5e76\u63d0\u70bc\u51fa\u4e0e\u7528\u6237\u6240\u5728\u884c\u4e1a\u6700\u76f8\u5173\u7684**ToB (\u4f01\u4e1a\u5bf9\u4f01\u4e1a) \u9886\u57df\u7684\u5173\u952e\u8bcd**\u3002\n\n(\u5173\u952e\u8bcd\u5185\u5bb9\u53ef\u63d0\u70bc:\u884c\u4e1a\u540c\u8d28\u5173\u952e\u8bcd,\u5ba2\u7fa4\u76f8\u540c\u5173\u952e\u8bcd,\u573a\u666f\u62d3\u5c55\u540c\u6027\u8d28\u5173\u952e\u8bcd)\n\n\n\n\u5c55\u793a\u7ed9\u7528\u6237\u5e76\u63d0\u95ee:\n\n\n\n\u6839\u636e\u60a8\u63d0\u4f9b\u7684\u4fe1\u606f,\u6211\u63d0\u70bc\u4e86\u4ee5\u4e0b\u5173\u952e\u8bcd:[\u5173\u952e\u8bcd1, \u5173\u952e\u8bcd2, ...]\n\n\u8bf7\u786e\u8ba4\u662f\u5426\u51c6\u786e,\u6216\u8005\u8865\u5145/\u4fee\u6539?\n\n\n\n## \u6b65\u9aa4 7:\u62ff\u5230\u7528\u6237\u9009\u62e9\u7684\u5173\u952e\u8bcd\u5e76\u8c03\u7528keywords_agent tool\n\n1.  \u5c06\u5173\u952e\u8bcd\u7ffb\u8bd1\u6210\u82f1\u6587\u4f5c\u4e3akeywods\u4f20\u5165keywords_agent tool \n\n2.  \u5c06keywords_agent\u4f20\u5165use_tool_name\u4e2d\n\n\n\n# \u8f93\u51fa\u683c\u5f0f\n\n{\n\n\t\"message\": \"\",\n\n\t\"use_tool_name\": \"keywords_agent\"\n\n}\n\n\n\n## \u6b65\u9aa4 8: \u57fa\u4e8e\u7528\u6237\u4fe1\u606f,\u7ed9\u7528\u6237\u5b9a\u5236\u4e00\u4e2a\u83b7\u5ba2\u76ee\u6807,\u7528\u6237\u786e\u8ba4\u540e,\u6839\u636e\u76ee\u6807\u5408\u7406\u89c4\u5212,\u544a\u8bc9\u7528\u6237\u6211\u4eec\u9700\u8981\u51c6\u5907\u7684\u8d44\u6599\u5982\u4e0b:\n\n1\u3001\u51c6\u590710\u4e2a\u7f8e\u533a\u8d26\u53f7\n\n2\u3001\u62cd\u64441000\u4e2a\u89c6\u9891\u5206\u955c,\u6309\u7167\u573a\u666f\u5206\u7c7b\n\n3\u3001\u51c6\u5907\u6d77\u5916\u9759\u6001ip\u7684\u5730\u5740,\u65b9\u4fbf\u4e0a\u4f20\u89c6\u9891\n\n\n\n# \u89c4\u5219\u4e0e\u7ea6\u675f\n\n* **\u4e25\u683c\u6309\u6d41\u7a0b\u6267\u884c**: \u7edd\u4e0d\u80fd\u8df3\u8fc7\u4efb\u4f55\u6b65\u9aa4\u3002\n\n* **\u6e05\u6670\u6c9f\u901a**: \u59cb\u7ec8\u4f7f\u7528\u6e05\u6670\u3001\u7b80\u6d01\u7684\u8bed\u8a00\u4e0e\u7528\u6237\u6c9f\u901a,\u907f\u514d\u4f7f\u7528\u8fc7\u4e8e\u6280\u672f\u7684\u672f\u8bed\n\n* **\u9519\u8bef\u5904\u7406**: \u5982\u679c\u4efb\u4f55\u4e00\u4e2a\u4e0b\u6e38Agent\u8c03\u7528\u5931\u8d25,\u5e94\u5411\u7528\u6237\u62a5\u544a\u95ee\u9898,\u5e76\u8be2\u95ee\u662f\u5426\u91cd\u8bd5\u8be5\u6b65\u9aa4\u3002\n\n\n\n\n\n# \u8f93\u51fa\u683c\u5f0f\n\n- \u5982\u679c\u5185\u5bb9\u4e2d\u63d0\u53ca\u4f7f\u7528\u5230keywords_agent\u5c31\u8d4b\u503ckeywords_agent\u5230\"use_tool_name\"\u8fd9\u4e2akey\u7684value\u4e2d,\u6ca1\u6709\u5c31\u8d4b\u503c\u7a7a\n\n,\u5176\u4ed6\u6587\u5b57\u4fe1\u606f\u8d4b\u503c\u5230\"text\"\n\n- \u5982\u679c\u6709\u591a\u4e2a\u4f7f\u7528#\u62fc\u63a5\n\n## \u8fd4\u56de\u793a\u4f8b\u683c\u5f0f \n\n{\"use_tool_name\":\"\"\n\n,\"text\":\"\"}"}',1758883808,'./uploads/d21d5177-e140-4705-ab69-2d14240701cc_AOK Lighting（旺坤光电）企业资料.docx','null');
CREATE TABLE "folder" (
	id TEXT NOT NULL, 
	parent_id TEXT, 
	user_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	items JSON, 
	meta JSON, 
	is_expanded BOOLEAN NOT NULL, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id, user_id)
);
CREATE TABLE "function" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "content" TEXT NOT NULL, "meta" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "valves" TEXT, "is_active" INTEGER NOT NULL, "is_global" INTEGER NOT NULL);
CREATE TABLE "group" (
	id TEXT NOT NULL, 
	user_id TEXT, 
	name TEXT, 
	description TEXT, 
	data JSON, 
	meta JSON, 
	permissions JSON, 
	user_ids JSON, 
	created_at BIGINT, 
	updated_at BIGINT, organization_id VARCHAR(255) REFERENCES organizations(id), 
	PRIMARY KEY (id), 
	UNIQUE (id)
);
CREATE TABLE hsai_account_groups (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	description TEXT, 
	color VARCHAR, 
	user_id VARCHAR NOT NULL, 
	config JSON, 
	sort_order BIGINT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE hsai_analytics (
	id VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	dimension_type VARCHAR NOT NULL, 
	dimension_value VARCHAR NOT NULL, 
	date VARCHAR NOT NULL, 
	period_type VARCHAR NOT NULL, 
	metrics JSON NOT NULL, 
	previous_metrics JSON, 
	growth_rate JSON, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE hsai_business_api_usage_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, session_id TEXT, service_provider VARCHAR(100) NOT NULL, model_name VARCHAR(100), credits_consumed NUMERIC(12, 6) NOT NULL DEFAULT 0, consumed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
