CREATE TABLE hsai_cards (
	id VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT, 
	card_type VARCHAR NOT NULL, 
	status VARCHAR, 
	user_id VARCHAR NOT NULL, 
	chat_id VARCHAR, 
	task_id VARCHAR, 
	content JSON, 
	config JSON, 
	actions JSON, 
	position JSON, 
	style JSON, 
	is_pinned BOOLEAN, 
	is_collapsed BOOLEAN, 
	sort_order BIGINT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES hsai_tasks (id)
);
CREATE TABLE hsai_material_folders (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	description TEXT, 
