CREATE TABLE hsai_material_tags (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	color VARCHAR, 
	category VARCHAR, 
	user_id VARCHAR NOT NULL, 
	usage_count BIGINT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE hsai_materials (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	description TEXT, 
	material_type VARCHAR NOT NULL, 
	folder_id VARCHAR, 
	user_id VARCHAR NOT NULL, 
	file_path VARCHAR, 
	file_size BIGINT, 
	file_hash VARCHAR, 
	mime_type VARCHAR, 
	material_metadata JSON, 
	tags JSON, 
	ai_analysis JSON, 
	usage_count BIGINT, 
	last_used_at BIGINT, 
	status VARCHAR, 
	access_control JSON, 
	created_at BIGINT, 
	updated_at BIGINT, scene_code VARCHAR, technique_code VARCHAR, properties_code VARCHAR, duration INTEGER, resolution VARCHAR, oss_bucket VARCHAR, oss_key VARCHAR, is_deleted BOOLEAN, original_directory VARCHAR, deleted_at BIGINT, deleted_by VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(folder_id) REFERENCES hsai_material_folders (id)
);
