CREATE TABLE hsai_platform_accounts (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	platform_type VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	platform_account_id VARCHAR NOT NULL, 
	username VARCHAR NOT NULL, 
	display_name VARCHAR, 
	avatar_url VARCHAR, 
	access_token TEXT, 
	refresh_token TEXT, 
	token_expires_at BIGINT, 
	config JSON, 
	permissions JSON, 
	status VARCHAR, 
	last_sync_at BIGINT, 
	follower_count BIGINT, 
	following_count BIGINT, 
	posts_count BIGINT, 
	tags JSON, 
	group_id VARCHAR, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(group_id) REFERENCES hsai_account_groups (id)
);
CREATE TABLE [hsai_projects] (
    id VARCHAR NOT NULL PRIMARY KEY,
    name VARCHAR NOT NULL,
    description TEXT,
    business_name VARCHAR NOT NULL,
    company_info JSON,
    user_id VARCHAR NOT NULL,
    status VARCHAR DEFAULT 'active',
    config JSON,
    created_at BIGINT,
    updated_at BIGINT
, company_id VARCHAR(255) REFERENCES companies(id));
