CREATE TABLE hsai_publish_records (
	id VARCHAR NOT NULL, 
	publish_task_id VARCHAR NOT NULL, 
	platform_account_id VARCHAR NOT NULL, 
	platform_post_id VARCHAR, 
	platform_url VARCHAR, 
	status VARCHAR NOT NULL, 
	error_message TEXT, 
	publish_data JSON, 
	response_data JSON, 
	views BIGINT, 
	likes BIGINT, 
	comments BIGINT, 
	shares BIGINT, 
	published_at BIGINT, 
	last_stats_update_at BIGINT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(publish_task_id) REFERENCES hsai_publish_tasks (id), 
	FOREIGN KEY(platform_account_id) REFERENCES hsai_platform_accounts (id)
);
CREATE TABLE hsai_publish_tasks (
	id VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT, 
	user_id VARCHAR NOT NULL, 
	hsai_task_id VARCHAR, 
	content JSON NOT NULL, 
	content_type VARCHAR NOT NULL, 
	platforms JSON NOT NULL, 
	publish_config JSON, 
	status VARCHAR, 
	progress BIGINT, 
	scheduled_at BIGINT, 
	published_at BIGINT, 
	error_message TEXT, 
	retry_count BIGINT, 
	tags JSON, 
	priority BIGINT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE "hsai_tasks" (
	id VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT, 
	task_type VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	chat_id VARCHAR, 
	config JSON, 
	inputs JSON, 
	outputs JSON, 
	workflow_id VARCHAR, 
	parent_task_id VARCHAR, 
	progress BIGINT NOT NULL, 
	started_at BIGINT, 
	completed_at BIGINT, 
	error_message TEXT, 
	retry_count BIGINT NOT NULL, 
	priority BIGINT, 
	tags JSON, 
	created_at BIGINT, 
	updated_at BIGINT, 
	assignee_id VARCHAR, 
	collaborators JSON, 
	shared_sessions JSON, project_id VARCHAR REFERENCES hsai_projects(id), task_category VARCHAR, prompt_config JSON, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_task_id) REFERENCES hsai_tasks (id), 
	FOREIGN KEY(workflow_id) REFERENCES hsai_workflows (id)
);
