CREATE TABLE hsai_viral_videos (
	id VARCHAR NOT NULL, 
	video_url VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT, 
	thumbnail_url VARCHAR, 
	duration INTEGER, 
	platform VARCHAR NOT NULL, 
	tags JSON, 
	metadata JSON, 
	status VARCHAR NOT NULL, 
	is_learned BOOLEAN NOT NULL, 
	material_id VARCHAR, 
	task_id VARCHAR, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	processed_at BIGINT, 
	learned_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE hsai_workflow_executions (
	id VARCHAR NOT NULL, 
	workflow_id VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	trigger_task_id VARCHAR, 
	status VARCHAR, 
	progress BIGINT, 
	inputs JSON, 
	outputs JSON, 
	execution_log JSON, 
	started_at BIGINT, 
	completed_at BIGINT, 
	error_message TEXT, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(workflow_id) REFERENCES hsai_workflows (id), 
	FOREIGN KEY(trigger_task_id) REFERENCES hsai_tasks (id)
);
CREATE TABLE hsai_workflows (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	description TEXT, 
	user_id VARCHAR NOT NULL, 
	definition JSON NOT NULL, 
	variables JSON, 
	status VARCHAR, 
	version VARCHAR, 
	execution_count BIGINT, 
	last_executed_at BIGINT, 
	category VARCHAR, 
	tags JSON, 
	created_at BIGINT, 
	updated_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE knowledge (
	id TEXT NOT NULL, 
	user_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	description TEXT, 
	data JSON, 
	meta JSON, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT, access_control JSON, 
	PRIMARY KEY (id)
);
CREATE TABLE "memory" ("id" VARCHAR(255) NOT NULL, "user_id" VARCHAR(255) NOT NULL, "content" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE message (
	id TEXT NOT NULL, 
	user_id TEXT, 
	channel_id TEXT, 
	content TEXT, 
	data JSON, 
	meta JSON, 
	created_at BIGINT, 
	updated_at BIGINT, parent_id TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (id)
);
CREATE TABLE message_reaction (
	id TEXT NOT NULL, 
	user_id TEXT NOT NULL, 
	message_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	created_at BIGINT, 
	PRIMARY KEY (id), 
	UNIQUE (id)
);
CREATE TABLE "migratehistory" ("id" INTEGER NOT NULL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, "migrated_at" DATETIME NOT NULL);
