CREATE TABLE trade_ticket (
	id VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	amount NUMERIC(24, 12), 
	detail JSON, 
	created_at BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE "user" ("id" VARCHAR(255) NOT NULL, "name" VARCHAR(255) NOT NULL, "email" VARCHAR(255) NOT NULL, "role" VARCHAR(255) NOT NULL, "profile_image_url" TEXT NOT NULL NOT NULL, "api_key" VARCHAR(255), "created_at" INTEGER NOT NULL NOT NULL, "updated_at" INTEGER NOT NULL NOT NULL, "last_active_at" INTEGER NOT NULL NOT NULL, "settings" TEXT, "info" TEXT, "oauth_sub" TEXT, info_collection_completed INTEGER DEFAULT 0, business_name TEXT NULL, company_id VARCHAR(255) REFERENCES companies(id), organization_id VARCHAR(255) REFERENCES organizations(id), is_super_admin BOOLEAN DEFAULT FALSE, is_org_admin BOOLEAN DEFAULT FALSE, credit_balance REAL DEFAULT 0.0);
